import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Line, Bar } from 'react-chartjs-2';
import jsPDF from 'jspdf';
import html2canvas from 'html2canvas';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, 
  BarElement, Title, Tooltip, Legend, Filler
} from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, BarElement, Title, Tooltip, Legend, Filler);

function App() {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [activeTab, setActiveTab] = useState("Dashboard");
  const [data, setData] = useState(null);
  const [selectedStock, setSelectedStock] = useState("HDFCBANK.NS");
  const [loading, setLoading] = useState(false);

  // 💰 STEP K: VIRTUAL WALLET (Fake Money Transaction)
  const [wallet, setWallet] = useState(100000); // Initial 1 Lakh INR
  const [portfolioHoldings, setPortfolioHoldings] = useState({}); // Stores quantity of each stock

  const stockList = [
    { name: "HDFC Bank", symbol: "HDFCBANK.NS" },
    { name: "SBI", symbol: "SBIN.NS" },
    { name: "Reliance", symbol: "RELIANCE.NS" },
    { name: "TCS", symbol: "TCS.NS" },
    { name: "ITC", symbol: "ITC.NS" }
  ];

  // 💹 EXECUTE VIRTUAL TRADE
  const executeTrade = (action) => {
    if (!data) return;
    const price = data.current_price;
    const symbol = data.symbol;

    if (action === "BUY") {
      if (wallet >= price) {
        setWallet(prev => prev - price);
        setPortfolioHoldings(prev => ({ ...prev, [symbol]: (prev[symbol] || 0) + 1 }));
        alert(`AI Trade Success: Bought 1 share of ${symbol} at ₹${price}`);
      } else {
        alert("Insufficient balance in Virtual Wallet!");
      }
    } else if (action === "SELL") {
      if (portfolioHoldings[symbol] > 0) {
        setWallet(prev => prev + price);
        setPortfolioHoldings(prev => ({ ...prev, [symbol]: prev[symbol] - 1 }));
        alert(`AI Trade Success: Sold 1 share of ${symbol} at ₹${price}`);
      } else {
        alert("You don't own any shares of this asset to sell!");
      }
    }
  };

  const fetchData = (symbol) => {
    setLoading(true);
    axios.get(`http://localhost:8000/api/analyze?tickers=${symbol}`)
      .then(res => {
        const result = Array.isArray(res.data) ? res.data[0] : res.data;
        setData(result);
        setLoading(false);
      })
      .catch(err => { console.error(err); setLoading(false); });
  };

  useEffect(() => { if (isLoggedIn) fetchData(selectedStock); }, [selectedStock, isLoggedIn]);

  const downloadReport = () => {
    const input = document.getElementById('report-area');
    html2canvas(input).then((canvas) => {
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      pdf.addImage(imgData, 'PNG', 0, 0, 210, (canvas.height * 210) / canvas.width);
      pdf.save(`QuantShield_Analysis.pdf`);
    });
  };

  if (!isLoggedIn) {
    return (
      <div style={{ height: '100vh', display: 'flex', justifyContent: 'center', alignItems: 'center', background: 'linear-gradient(45deg, #1e293b, #334155)', color: 'white', fontFamily: 'sans-serif' }}>
        <div style={{ textAlign: 'center', padding: '50px', background: 'rgba(255,255,255,0.1)', borderRadius: '20px', backdropFilter: 'blur(10px)' }}>
          <h1>🛡️ QuantShield AI</h1>
          <p>Portfolio Optimization System</p>
          <button onClick={() => setIsLoggedIn(true)} style={{ marginTop: '20px', padding: '12px 40px', background: '#00f2fe', border: 'none', borderRadius: '10px', fontWeight: 'bold', cursor: 'pointer' }}>ENTER SYSTEM</button>
        </div>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', backgroundColor: '#f4f7fe', minHeight: '100vh', fontFamily: "'Jakarta Sans', sans-serif" }}>
      {/* SIDEBAR */}
      <div style={{ width: '260px', background: 'white', padding: '30px 20px', borderRight: '1px solid #e2e8f0' }}>
        <h2 style={{ color: '#4facfe', fontWeight: '800' }}>QuantShield</h2>
        <div style={{ marginTop: '40px' }}>
          {["Dashboard", "Analytics", "Settings"].map(tab => (
            <div key={tab} onClick={() => setActiveTab(tab)} style={{ background: activeTab === tab ? '#f4f7fe' : 'transparent', color: activeTab === tab ? '#4facfe' : '#64748b', padding: '15px', borderRadius: '12px', fontWeight: 'bold', marginBottom: '10px', cursor: 'pointer' }}>{tab}</div>
          ))}
        </div>
      </div>

      {/* MAIN CONTENT */}
      <div style={{ flex: 1, padding: '40px' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '30px' }}>
          <h1 style={{ fontSize: '28px', fontWeight: '800' }}>{activeTab}</h1>
          <div style={{ display: 'flex', gap: '15px', alignItems: 'center' }}>
            <div style={{ background: 'white', padding: '10px 20px', borderRadius: '12px', border: '1px solid #e2e8f0', boxShadow: '0 4px 10px rgba(0,0,0,0.02)' }}>
              <span style={{ fontSize: '12px', color: '#64748b' }}>DEMO WALLET: </span>
              <b style={{ color: '#22c55e' }}>₹{wallet.toLocaleString()}</b>
            </div>
            {activeTab === "Dashboard" && <button onClick={downloadReport} style={{ padding: '10px 20px', background: '#1e293b', color: 'white', borderRadius: '10px', border: 'none', cursor: 'pointer' }}>Download Report</button>}
          </div>
        </div>

        <div id="report-area">
          {activeTab === "Dashboard" && data && (
            <>
              {/* 🟢 STEP K: VIRTUAL TRADE PANEL */}
              <div style={{ display: 'grid', gridTemplateColumns: '2fr 1fr', gap: '25px', marginBottom: '30px' }}>
                <div style={{ background: 'white', padding: '25px', borderRadius: '24px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <h3 style={{ margin: 0 }}>Trade Asset: {data.symbol}</h3>
                    <p style={{ color: '#64748b', margin: '5px 0' }}>Holdings: <b>{portfolioHoldings[data.symbol] || 0} Shares</b></p>
                  </div>
                  <div style={{ display: 'flex', gap: '15px' }}>
                    <button onClick={() => executeTrade("BUY")} style={{ padding: '15px 35px', background: '#22c55e', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>BUY</button>
                    <button onClick={() => executeTrade("SELL")} style={{ padding: '15px 35px', background: '#ef4444', color: 'white', border: 'none', borderRadius: '12px', fontWeight: 'bold', cursor: 'pointer' }}>SELL</button>
                  </div>
                </div>
                <div style={{ background: data.decision === "BUY" ? '#f0fdf4' : '#fef2f2', padding: '25px', borderRadius: '24px', textAlign: 'center', border: `2px solid ${data.decision === "BUY" ? '#22c55e' : '#ef4444'}` }}>
                  <div style={{ fontSize: '12px', color: '#64748b' }}>AI VERDICT (STEP I)</div>
                  <div style={{ fontSize: '32px', fontWeight: '900', color: data.decision === "BUY" ? '#166534' : '#991b1b' }}>{data.decision}</div>
                </div>
              </div>

              {/* STATS CARDS */}
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '30px' }}>
                <MiniCard title="Current Price" value={`₹${data.current_price}`} color="#4facfe" />
                <MiniCard title="Volatility" value={data.volatility} color="#f85149" />
                <MiniCard title="BSI Score" value={data.bsi_score} color="#d2a8ff" />
                <MiniCard title="Regime" value={data.regime} color={data.regime === "STRESS" ? "#ef4444" : "#22c55e"} />
              </div>
            </>
          )}

          {activeTab === "Analytics" && (
            <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
              <h3 style={{ marginBottom: '20px' }}>📊 Optimized Asset Comparison</h3>
              <div style={{ height: '350px' }}>
                <Bar 
                  data={{
                    labels: ['HDFC', 'SBI', 'Reliance', 'TCS', 'ITC'],
                    datasets: [{
                      label: 'Risk Score (Lower is Better)',
                      data: [15, 25, 20, 10, 12],
                      backgroundColor: ['#4facfe', '#f85149', '#3fb950', '#f1e05a', '#d2a8ff'],
                      borderRadius: 8
                    }]
                  }} 
                  options={{ maintainAspectRatio: false }} 
                />
              </div>
              <div style={{ marginTop: '20px', padding: '20px', background: '#f8fafc', borderRadius: '15px', border: '1px solid #e2e8f0' }}>
                <h4 style={{ color: '#4facfe' }}>🤖 AI Portfolio Advice for Madam</h4>
                <p style={{ fontSize: '14px', color: '#64748b' }}>Portfolio health is <b>88%</b>. Suggested to rebalance 5% from SBI to TCS for stability.</p>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
          {activeTab === "Stocks" && (
             <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
               <h3>💹 Asset Watchlist</h3>
               <table style={{ width: '100%', borderCollapse: 'collapse', marginTop: '20px' }}>
                 <thead><tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b' }}><th style={{ padding: '15px', textAlign: 'left' }}>Stock</th><th style={{ textAlign: 'left' }}>Price</th><th style={{ textAlign: 'left' }}>Action</th></tr></thead>
                 <tbody>{stockList.map(s => (<tr key={s.symbol} style={{ borderBottom: '1px solid #f1f5f9' }}><td style={{ padding: '15px', fontWeight: 'bold' }}>{s.name}</td><td>₹{s.symbol === "HDFCBANK.NS" ? "816.70" : "1,140.25"}</td><td><button onClick={() => { setSelectedStock(s.symbol); setActiveTab("Dashboard"); }} style={{ background: '#4facfe', color: 'white', border: 'none', padding: '5px 15px', borderRadius: '5px', cursor: 'pointer' }}>Analyze</button></td></tr>))}</tbody>
               </table>
             </div>
          )}

          {activeTab === "Settings" && (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 2fr', gap: '25px' }}>
               <div style={{ background: 'white', padding: '30px', borderRadius: '24px', textAlign: 'center' }}>
                  <div style={{ width: '80px', height: '80px', borderRadius: '50%', background: '#4facfe', margin: '0 auto 20px', color: 'white', fontSize: '30px', display: 'flex', justifyContent: 'center', alignItems: 'center' }}>S</div>
                  <h3>Suresh M</h3>
                  <p>Verified Quant Account</p>
               </div>
               <div style={{ background: 'white', padding: '30px', borderRadius: '24px' }}>
                  <h4>System Preferences</h4>
                  <p>Ghost Hedge: <b>ENABLED</b> ✅</p>
                  <button style={{ padding: '10px 20px', background: '#f4f7fe', border: 'none', borderRadius: '8px', cursor: 'pointer' }}>Edit Security</button>
               </div>
            </div>
          )}
        

function MiniCard({ title, value, color }) {
  return (
    <div style={{ background: 'white', padding: '25px', borderRadius: '20px', border: '1px solid #f1f5f9', boxShadow: '0 4px 12px rgba(0,0,0,0.03)' }}>
      <div style={{ color: '#64748b', fontSize: '13px', marginBottom: '5px', fontWeight: 'bold' }}>{title}</div>
      <div style={{ fontSize: '24px', fontWeight: '800', color: '#1e293b' }}>{value}</div>
      <div style={{ marginTop: '10px', width: '40px', height: '4px', background: color, borderRadius: '2px' }}></div>
    </div>
  );
}

export default App;
